      "id": "mage_storm",
      "className": "Mage",
      "name": "Storm Caller",
      "summary": "A lightning caster that shocks everything it touches: chain and area spells, lightning damage and the Storm Caller keystone from the tree, and crits and haste from your buffs.",
      "playstyle": "Start with Elemental Focus so the next three spells crit, then chain Chain Lightning through the pack and drop Thunderstorm on the group. Use Ball Lightning and Overload Discharge to keep enemies shocked and interrupted. Haste speeds you up, Spell Ward absorbs the next magic hits and Blink gets you out.",
      "stats": [
        {
          "stat": "INT",
          "why": "Multiplies every Mage skill (+5% per point) and adds mana. The route takes it with the lightning and Storm Caller nodes."
        },
        {
          "stat": "WIS",
          "why": "Mana regeneration for a spell-heavy rotation, and part of the gem requirements."
        },
        {
          "stat": "DEX",
          "why": "Attack and cooldown speed, and the crit nodes of the Dexterity sector on the way."
        },
        {
          "stat": "CON",
          "why": "Only what the gem requirements ask for."
        }
      ],
